'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var Routine = require( './routine.js' );
var Module = require( './module.js' );


// MAIN //

/**
* WebAssembly module to compute the maximum value of a double-precision floating-point strided array according to a mask.
*
* @name dmskmax
* @type {Routine}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmax.main( x.length, x, 1, mask, 1 );
* // returns 2.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmax.ndarray( x.length, x, 1, 0, mask, 1, 0 );
* // returns 2.0
*/
var dmskmax = new Routine();
dmskmax.initializeSync(); // eslint-disable-line n/no-sync
setReadOnly( dmskmax, 'Module', Module.bind( null ) );


// EXPORTS //

module.exports = dmskmax;
